sp_widget.client_script:
function($scope,$rootScope,spModal,spUtil) {	
	var c = this;
	c.update = false;
	c.delete =  false;
	//const button = document.querySelector("input");
	//	c.updateButton = function() {
	//	if (button.value === "Display All Discs") {
	///	button.value = "Hide All Discs";
	//		} else {
	//	button.value = "Display All Discs";
	//	paragraph.textContent = "The machine is stopped.";		 
	//		}
	//	}	
	//const text = document.querySelector("select");	

	c.updateButton = function() {
		if (c.delete == true){
			c.delete = false; 			 
		}   

		if (c.update == false){
			if(!c.data.sys_id){
				spUtil.addInfoMessage('Please select any disc record from Display All Discs');
				return;
			}
			c.update = true; 
		} else {
			if (c.update == true){
				c.update = false; 
			} 
		}
		console.log('Dear JD, z disc c.update   c.update  je: ' + c.update);
		console.log('Dear JD, z disc c.update   c.delete  je: ' + c.delete);
	}


	c.displayChangedPriceDisc = function() {	
		console.log('Disc displayChangedPriceDisc z c.data.sys_id je  : ' + c.data.sys_id);
		console.log('Disc displayChangedPriceDisc z c.data.newCount je  : ' + c.data.newCount);
		console.log('Disc displayChangedPriceDisc z c.data.newPrice1 je  : ' + c.data.newPrice);	
	}	 

	c.updatePriceOrCount = function(newPriceOrCount){ //https://www.servicenow.com/community/developer-forum/how-to-get-drop-down-field-value-in-portal/m-p/2040642
		console.log('Disc  newPrice Or Count je  : ' + newPriceOrCount);
		console.log('Disc displayChangedPriceDisc z c.data.sys_id je  : ' + c.data.sys_id);
		if(c.data.sys_id ==='undefined'){
			console.log(' c.updatePrice sa nekona field1 je  : ' + newPriceOrCount + ' Update Stop !');
			return;
		}  else {
			$rootScope.discID = c.data.sys_id;
			console.log('JD  c.data.newPrice je  : ' + c.data.newPrice);
			console.log('JD c.data.newCount je  : ' +  c.data.newCount);

			c.server.get({
				action: 'updateDisc',
				discID: $rootScope.discID,
				discPrice: c.data.newPrice,
				discCount: c.data.newCount

			}).then(function(r){
				// When the promise is returned, emit the change			 
				$rootScope.$emit('updateDisc', r.data);
			}); 
			c.data.newPrice ='';
			c.data.newCount ='';
		}
	}

	$rootScope.$on('selectDisc', function(event,data){
		console.log('Dear JD, z body disc  ID  $rootScope.discID .$on  je: ' + $rootScope.discID);
		c.server.get({
			action: 'getDisc',
			discID: $rootScope.discID

		}).then(function(r){
			c.data.u_mark = r.data.discObject.u_mark;			 
			c.data.u_modell = r.data.discObject.u_modell;			
			c.data.u_performance = r.data.discObject.u_performance;
			c.data.u_count = r.data.discObject.u_count;
			c.data.u_price =  r.data.discObject.u_price;
			c.data.u_priceallpcs = r.data.discObject.u_priceallpcs;
			c.data.sys_id = r.data.discObject.sys_id;
		});		  
	});

	c.deleteButton = function(){
		if (c.update == true){
			c.update = false; 			 
		}   

		if (c.delete == false){
			if(!c.data.sys_id){
				spUtil.addInfoMessage('Please select any disc record from Display All Discs');
				return;
			}
			c.delete = true; 
			spModal.confirm("Are you sure you want to delete Disc record?").then(function(confirmed){
				if(confirmed){
					c.deleteDisc();
				}
			});
		} else {
			if (c.delete == true){
				c.delete = false; 
			} 
		}
		console.log('Dear JD, z disc c.update   c.update  je: ' + c.update);
		console.log('Dear JD, z disc c.update   c.delete  je: ' + c.delete);
	}

	c.deleteDisc  = function(){
		console.log('Disc c.deleteDisc() z c.data.sys_id je  : ' + c.data.sys_id);

		c.server.get({
			action: 'deleteDisc',
			discID: c.data.sys_id
		}).then(function(r){

			$rootScope.$emit('deleteDisc', c.data.sys_id);
			c.data.u_mark = '';			 
			c.data.u_modell = '';			
			c.data.u_performance = '';
			c.data.u_count = '';
			c.data.u_price = '';
			c.data.u_priceallpcs = '';
			c.data.sys_id = '';
		});
	}
	$scope.prics = ['15','20','25','30','35','40','45','50'];
	$scope.cnts = ["2","4","6","8","10"];
}

sp_widget.script:
(function() {
	/* populate the 'data' object */
	/* e.g., data.table = $sp.getValue('table'); */	 

	if(input && input.discID){
		var oneDiscGR = new GlideRecord('x_1461179_disk_sho_disc_bmw_admin');		

		if(oneDiscGR.get(input.discID)){
			if(input.action =='getDisc'){				 
				data.discObject = {};
				//	$sp.getRecordValues(data.discObject, oneDiscGR, "u_mark, u_modell, u_performance, u_count, u_price, u_priceallpcs"); // vrati len cisla values
				$sp.getRecordDisplayValues(data.discObject, oneDiscGR, "u_mark, u_modell, u_performance, u_count, u_price, u_priceallpcs, sys_id");  // vrati hodnoty labels
			} else {
				if(input.action =='updateDisc'){						 
					var price = parseInt(input.discPrice);
					var count = parseInt(input.discCount);
					var originalCount = parseInt(oneDiscGR.getValue('u_count'));				 
					var pricAll = '';

					if((price)){
						oneDiscGR.u_price = price;						 
						pricAll = (originalCount * price);
					} else {
						if((count)){
							var cnt = (count + originalCount);
							oneDiscGR.u_count = cnt;
							var originalPrice = parseInt(oneDiscGR.getValue('u_price'));
							pricAll = cnt * originalPrice;
						}
					}
					oneDiscGR.u_priceallpcs = pricAll;	
					oneDiscGR.update();				
					data.u_price = oneDiscGR.getValue('u_price');
					data.u_count = oneDiscGR.getValue('u_count');					 
					data.u_priceallpcs = oneDiscGR.getValue('u_priceallpcs');							
				} else {
					if(input.action =='deleteDisc'){					 
						oneDiscGR.deleteRecord();
					}
				}
			}
		}
	}

})();
